/* Policy page styles */
.policy-page {
  background: var(--bg);
  color: var(--text);
  font-family: 'Poppins', sans-serif;
  line-height: 1.6;
  padding: 20px;
}
.policy-container {
  max-width: 800px;
  margin: 0 auto;
  background: var(--card);
  padding: 40px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
}
.policy-container h1 {
  color: var(--gold-on-dark);
  font-family: 'Playfair Display', serif;
  font-size: 2.5rem;
  margin-bottom: 1.5rem;
}
.policy-container h2 {
  color: var(--gold-on-dark);
  font-family: 'Playfair Display', serif;
  font-size: 1.75rem;
  margin-top: 2rem;
  margin-bottom: 1rem;
}
.policy-container a {
  color: var(--gold-on-dark);
}
.policy-container p {
  margin-bottom: 1rem;
  text-wrap: pretty;
}

