  margin-bottom: 1.5rem;
}
.policy-container h2 {
  color: var(--gold-on-dark);
  font-family: 'Playfair Display', serif;
  font-size: 1.75rem;
  margin-top: 2rem;
  margin-bottom: 1rem;
}
.policy-container a {
  color: var(--gold-on-dark);
}
.policy-container p {
  margin-bottom: 1rem;
  text-wrap: pretty;
}

/* Admin page styles */
.admin-container {
  padding: 40px 20px;
  max-width: 1000px;
  margin: 0 auto;
}
.admin-container > h1 {
  text-align: center;
  color: var(--gold-on-dark);
  margin-bottom: 20px;
}
.admin-logout {
  position: absolute;
  top: 20px;
  right: 20px;
}
.admin-section {
  background: var(--card);
  padding: 20px;
  margin-bottom: 20px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
}
.admin-section h2 {
  color: var(--gold-on-dark);
  margin-bottom: 20px;
}
.form-group {
  margin-bottom: 15px;
}
.form-group label {
  display: block;
  margin-bottom: 5px;
  color: var(--text);
}
.form-group input,
.form-group textarea {
  width: 100%;
  padding: 10px;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 5px;
  color: var(--text);
}
.card-item {
  background: var(--bg);
  padding: 15px;
  margin-bottom: 10px;
  border-radius: 5px;
  border: 1px solid var(--line);
}
.card-item h3 {
  margin-top: 0;
  color: var(--gold-on-dark);
}
.btn-admin {
  background: var(--gold-on-dark);
  color: #111;
  border: none;
  padding: 10px 15px;
  border-radius: 5px;
  cursor: pointer;
  margin-right: 10px;
}
.btn-admin:hover {
  background: var(--gold);
  color: #111;
}
.btn-remove {
  background: #d9534f;
  color: white;
  border: none;
  padding: 5px 10px;
  border-radius: 3px;
  cursor: pointer;
}
.preview {
  max-width: 100px;
  margin-top: 10px;
}
.hero-badges {
  margin-top: 20px;
}
.badge-item {
  display: flex;
  align-items: center;
  margin-bottom: 10px;
}
.badge-item input {
  margin-left: 10px;
}
.album-photos-list li {
  display: flex;
  align-items: center;
  margin-bottom: 5px;
}
.album-photos-list input {
  flex-grow: 1;
  margin-right: 10px;
}
.file-input-container {
  position: relative;
  margin-bottom: 10px;
}
.file-input-button {
  background: var(--gold-on-dark);
  color: #111;
  border: none;
  padding: 8px 12px;
  border-radius: 3px;
  cursor: pointer;
  font-size: 12px;
}
.file-input-button:hover {
  background: var(--gold);
  color: #111;
}
.file-input-hidden {
  position: absolute;
  left: -9999px;
}
.current-file {
  font-size: 12px;
  color: var(--text-light);
  margin-top: 5px;
}
.photo-item {
  display: flex;
  align-items: center;
  margin-bottom: 10px;
  padding: 10px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 5px;
}
.photo-preview {
  width: 80px;
  height: 60px;
  object-fit: cover;
  margin-right: 10px;
  border-radius: 3px;
}
.photo-info {
  flex-grow: 1;
}
.photo-url-display {
  font-size: 11px;
  color: var(--text-light);
  word-break: break-all;
}
.admin-note {
  font-size: 12px;
  color: var(--text-light);
  margin-top: -10px;
  margin-bottom: 10px;
}

